const WINDOWS = [['2026-08-20', '2026-08-23'], ['2026-08-24', '2026-08-27']];
const EVENTS = ['translation.updated', 'translations.updated'];
const out = [];
for (const u of LINGUISTS) {
  for (const ev of EVENTS) {
    for (const w of WINDOWS) {
      out.push({ json: { user_id: u.id, email: u.email, event_type: ev, date_from: w[0], date_to: w[1] } });
    }
  }
}
return out;

const RC = { '964775386a3ce03ecca883.03770715': 'Realchecker (FE)', '852017176a3ce11141ecd5.60405885': 'Realchecker (BE)' };
const reqs = $('Build Audit Requests').all();
const res = $input.all();
const statuses = {};
const failed = [];
const more = [];
const byProjectAll = {};
const edits = {};
let totalEvents = 0;

function projectOf(ev) {
  for (const e of (ev.enrichments || [])) {
    if ((e.name || '') === 'project' && e.data && e.data.id) { return String(e.data.id); }
  }
  return null;
}

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  const meta = metaItem ? metaItem.json : {};
  const r = res[i].json || {};
  const body = r.body || {};
  statuses[String(r.statusCode)] = (statuses[String(r.statusCode)] || 0) + 1;
  if (r.statusCode !== 200) { failed.push(meta.email + '/' + meta.event_type + '/' + meta.date_from + ' -> ' + r.statusCode); continue; }
  if (body.has_more) { more.push(meta.email + '/' + meta.event_type + '/' + meta.date_from); }
  for (const ev of (body.data || [])) {
    totalEvents++;
    const pid = projectOf(ev);
    const pname = pid ? (RC[pid] || 'other') : 'no-project';
    byProjectAll[pname] = (byProjectAll[pname] || 0) + 1;
    if (!pid || !RC[pid]) { continue; }
    const d = (ev.unmapped && ev.unmapped.data) ? ev.unmapped.data : (ev.data || {});
    const ts = ev.time || null;
    if (d.translations && d.translations.length) {
      for (const t of d.translations) {
        const iso = (t.language && t.language.iso) ? String(t.language.iso).toLowerCase() : null;
        const kid = (t.key && t.key.id) ? t.key.id : null;
        if (!iso || !kid) { continue; }
        const kk = pid + '|' + kid + '|' + iso;
        if (!edits[kk] || Number(ts) > Number(edits[kk].ts)) { edits[kk] = { ts: ts, project_id: pid, project_name: pname, key_id: kid, lang_iso: iso, email: meta.email, user_id: meta.user_id, bulk: true }; }
      }
    } else {
      const iso = d.lang_iso ? String(d.lang_iso).toLowerCase() : null;
      const kid = d.key_id === undefined ? null : d.key_id;
      if (!iso || !kid) { continue; }
      const kk = pid + '|' + kid + '|' + iso;
      if (!edits[kk] || Number(ts) > Number(edits[kk].ts)) { edits[kk] = { ts: ts, project_id: pid, project_name: pname, key_id: kid, lang_iso: iso, email: meta.email, user_id: meta.user_id, bulk: false }; }
    }
  }
}

const rows = [];
for (const k in edits) { rows.push(edits[k]); }
rows.sort(function (a, b) { return Number(a.ts) - Number(b.ts); });

const byLang = {};
const byEmail = {};
const keyIdsByProject = {};
for (const r of rows) {
  byLang[r.lang_iso] = (byLang[r.lang_iso] || 0) + 1;
  byEmail[r.email] = (byEmail[r.email] || 0) + 1;
  if (!keyIdsByProject[r.project_id]) { keyIdsByProject[r.project_id] = {}; }
  keyIdsByProject[r.project_id][r.key_id] = 1;
}
const keyCounts = {};
const keyLists = {};
for (const pid in keyIdsByProject) {
  const ids = [];
  for (const kid in keyIdsByProject[pid]) { ids.push(Number(kid)); }
  ids.sort(function (a, b) { return a - b; });
  keyCounts[pid] = ids.length;
  keyLists[pid] = ids;
}
const langs = [];
for (const l in byLang) { langs.push(l); }
langs.sort();

return [{ json: { statuses: statuses, failed: failed, has_more_windows: more, total_events_all_projects: totalEvents, by_project_all: byProjectAll, realchecker_edit_rows: rows.length, languages: langs, by_language: byLang, by_linguist: byEmail, key_counts: keyCounts, key_lists: keyLists, rows: rows } }];
